release_by_song_id = {}
for album in apis.spotify.show_album_library(access_token=token, page_index=idx):
    for song_id in album.song_ids:
        try:
            detail = apis.spotify.show_song(song_id=song_id)
            release_by_song_id[song_id] = detail.release_date
        except Exception:
            release_by_song_id.setdefault(song_id, album.release_date)
